"use server";

import { revalidatePath } from "next/cache";

// Simple in-memory store for demonstration
let notificationEnabled = false;

export async function getNotificationPreference(): Promise<boolean> {
  return notificationEnabled;
}

export async function toggleNotification(): Promise<void> {
  notificationEnabled = !notificationEnabled;

  // Revalidate the current path to refresh the page data
  revalidatePath("/");
}

import { toggleNotification, getNotificationPreference } from "./actions";

export default async function Home() {
  const isEnabled = await getNotificationPreference();

  return (
    <main>
      <h1>Settings</h1>
      <div style={{ marginTop: "1rem" }}>
        <p>
          Notifications are currently: {" "}
          <strong>{isEnabled ? "ON" : "OFF"}</strong>
        </p>
        <form action={toggleNotification}>
          <button type="submit">
            Turn {isEnabled ? "OFF" : "ON"}
          </button>
        </form>
      </div>
    </main>
  );
}
